"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 4 (P1 v0.4, section 5.3): check, then split, the new lines (prompts: configs/checker_prompts_v2.md).

prepare: candidates (data/lines_v04/pools_candidates.json, convlines_candidates.json) -> punctuated (v0.3 rule),
         normalised and deduplicated pool lines (answer lines equal to a v0.3 flip line are dropped: flip lines are a
         separate, common source) -> check items with the full question text, shuffled (seeded) into batches of about
         300 (data/lines_v04/check/batch_XX.json). The checker is not told any split.
collect: read the checker answers (batch_XX.out.json; complete and in order), apply the pass rules and write
         results/step0_v04/line_check.json.
assign:  pools split by phrasing after the check: answers (phone, door) and keep-going lines go to exactly one split
         (seeded: train 50%, dev 15%, test 20%, replication 15%); backchannels that pass for all three events are
         common to all splits; per-conversation lines keep their conversation's split. Minimums (plan 5.3): phone
         answers 100, door answers 50, keep-going 60, backchannels 8. Writes results/step0_v04/lines_v04.json.
usage: python -I scripts/step0v4_lines.py prepare|collect|assign
"""
import glob
import json
import os
import random
import sys
from collections import Counter

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from step0_check_batches import norm, punctuate  # noqa: E402

LINES = "data/lines_v04"
CHK = f"{LINES}/check"
SEED = 20261115
S0 = ("At home, a person is in the middle of a conversation with a voice assistant (a smart speaker). Right now the "
      "assistant is not speaking.")
S1 = ("At home, a person's voice assistant (a smart speaker) is in the middle of talking to them, for example reading "
      "out a recipe or directions.")
EVENT_TEXT = {"phone": "Their phone starts ringing", "knock": "Someone knocks on the front door",
              "doorbell": "The doorbell rings"}
MINIMUMS = {"phone_answer": 100, "door_answer": 50, "keep_going": 60, "backchannel": 8}


def flip_norms():
    la = json.load(open("results/step0/line_assignment.json", encoding="utf-8"))
    out = set()
    for kind in ("phone_flip", "door_flip"):
        for k in ("common", "test_only"):
            out |= {norm(x) for x in la["flip"][kind].get(k, [])}
    return out


def pool_lines():
    pools = json.load(open(f"{LINES}/pools_candidates.json", encoding="utf-8"))
    flips = flip_norms()
    out = {}
    for kind, items in pools.items():
        seen = {}
        for it in items:
            line = punctuate(it["text"])
            k = norm(line)
            if not k or (kind in ("phone_answer", "door_answer") and k in flips) or (kind, k) in seen:
                continue
            seen[(kind, k)] = True
            out[f"{kind}:{len(out):05d}"] = {"kind": kind, "line": line, "event": it["event"], "norm": k}
    return out


def prepare():
    convs = json.load(open("results/step0/line_assignment.json", encoding="utf-8"))["conversations"]
    cl = json.load(open(f"{LINES}/convlines_candidates.json", encoding="utf-8"))
    items = []
    for pid, p in pool_lines().items():
        kind, line = p["kind"], p["line"]
        if kind == "phone_answer":
            items.append({"id": pid, "prompt": f"{S0} Their phone starts ringing and they pick it up. Right after "
                          f"picking up, the person says: «{line}» Question: who is this said to? A = clearly the "
                          "caller; B = it could also be meant for the voice assistant; C = clearly the voice "
                          "assistant."})
        elif kind == "door_answer":
            items.append({"id": pid, "prompt": f"{S0} {EVENT_TEXT[p['event']]}. Before opening the door, the person "
                          f"calls out: «{line}» Question: who is this said to? A = clearly the person at the door; "
                          "B = it could also be meant for the voice assistant; C = clearly the voice assistant."})
        elif kind == "keep_going":
            items.append({"id": pid, "prompt": f"{S1} {EVENT_TEXT[p['event']]}. The person says: «{line}» Question: "
                          "what does the person want the assistant to do? A = clearly to keep talking; B = to stop, "
                          "pause or wait; C = unclear, or the line is meant for someone else."})
        else:
            for ev in ("phone", "knock", "doorbell"):
                items.append({"id": f"{pid}|{ev}", "prompt": f"{S1} {EVENT_TEXT[ev]}. The person does not pick up the "
                              f"phone and does not go to the door, and only says: «{line}» Question: A = the person is "
                              "clearly just listening to the assistant and letting it go on; B = the person is "
                              "answering the phone or the door, or talking to someone else; C = cannot tell."})
    for which, d in cl.items():
        for cid, v in d.items():
            split, idx = cid.rsplit("_", 1)
            c = convs[split][int(idx)]
            ctx = (f"{S0} Earlier the person asked the assistant: «{c['user_request']}» The assistant answered: "
                   f"«{c['agent_answer']}»")
            for field in (("plain", "hello_start") if which == "phone" else ("plain",)):
                line = punctuate(v.get(field, ""))
                if not norm(line):
                    continue
                if which == "phone":
                    q = (f"{ctx} Then the person's phone rang, and the ringing stopped. Someone in the room cannot tell "
                         f"whether the person picked up or declined the call. Right after the ringing stopped, the "
                         f"person says: «{line}» Question: who is this said to? A = clearly the voice assistant; "
                         "B = it could be the caller; C = clearly the caller.")
                else:
                    q = (f"{ctx} Then someone knocked on the front door or rang the doorbell, and the person did not "
                         f"go to the door. The person says: «{line}» Question: who is this said to? A = clearly the "
                         "voice assistant; B = it could be the person at the door; C = clearly the person at the door.")
                items.append({"id": f"conv_{which}:{cid}:{field}", "prompt": q})
    random.Random(SEED).shuffle(items)
    os.makedirs(CHK, exist_ok=True)
    n = max(1, round(len(items) / 300))
    size = -(-len(items) // n)
    for b in range(n):
        json.dump(items[b * size:(b + 1) * size], open(f"{CHK}/batch_{b:02d}.json", "w", encoding="utf-8"),
                  indent=1, ensure_ascii=False)
    print(f"{len(items)} items in {n} batches of about {size}:",
          dict(Counter(i["id"].split(":")[0].split("|")[0] for i in items)))


def collect():
    ans, bad = {}, []
    for f in sorted(glob.glob(f"{CHK}/batch_*.json")):
        if f.endswith(".out.json"):
            continue
        items = json.load(open(f, encoding="utf-8"))
        out_f = f[:-5] + ".out.json"
        if not os.path.exists(out_f):
            bad.append(f"missing {out_f}")
            continue
        out = json.load(open(out_f, encoding="utf-8"))
        if [o["id"] for o in out] != [i["id"] for i in items]:
            bad.append(f"order or ids differ in {out_f}")
        for o in out:
            if o.get("answer") not in ("A", "B", "C"):
                bad.append(f"bad answer {o}")
            ans[o["id"]] = o.get("answer")
    if bad:
        print("INCOMPLETE:", bad[:10])
        sys.exit(1)
    pools = pool_lines()
    res = {"pools": {}, "conv": {}}
    for pid, p in pools.items():
        if p["kind"] == "backchannel":
            ok = all(ans.get(f"{pid}|{ev}") == "A" for ev in ("phone", "knock", "doorbell"))
        else:
            ok = ans.get(pid) == "A"
        res["pools"][pid] = {**p, "pass": ok}
    for k, a in ans.items():
        if k.startswith("conv_"):
            res["conv"][k] = {"answer": a, "pass": a == "A"}
    json.dump(res, open("results/step0_v04/line_check.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    tab = Counter((p["kind"], p["pass"]) for p in res["pools"].values())
    print({k: f"{tab[(k, True)]}/{tab[(k, True)] + tab[(k, False)]}" for k in sorted({p["kind"] for p in pools.values()})})
    ct = Counter((k.split(":")[0], k.split(":")[2], v["pass"]) for k, v in res["conv"].items())
    print({f"{a}:{b}": f"{ct[(a, b, True)]}/{ct[(a, b, True)] + ct[(a, b, False)]}"
           for a, b in sorted({(x[0], x[1]) for x in ct})})


def assign():
    chk = json.load(open("results/step0_v04/line_check.json", encoding="utf-8"))
    rng = random.Random(SEED)
    out = {"seed": SEED, "pools": {}, "backchannel_common": [], "conv": {}}
    for kind in ("phone_answer", "door_answer", "keep_going"):
        ps = sorted((p for p in chk["pools"].values() if p["kind"] == kind and p["pass"]), key=lambda p: p["norm"])
        rng.shuffle(ps)
        n = len(ps)
        cut = [round(n * 0.50), round(n * 0.65), round(n * 0.85)]
        out["pools"][kind] = {sp: [{"line": p["line"], "event": p["event"]} for p in part] for sp, part in
                              (("train", ps[:cut[0]]), ("dev", ps[cut[0]:cut[1]]), ("test", ps[cut[1]:cut[2]]),
                               ("replication", ps[cut[2]:]))}
    out["backchannel_common"] = sorted(p["line"] for p in chk["pools"].values() if p["kind"] == "backchannel"
                                       and p["pass"])
    for k, v in chk["conv"].items():
        which, cid, field = k.split(":")
        split = cid.rsplit("_", 1)[0]
        out["conv"].setdefault(which, {}).setdefault(cid, {"split": split})[field] = v["pass"]
    counts = {k: sum(len(v) for v in out["pools"][k].values()) for k in out["pools"]}
    counts["backchannel"] = len(out["backchannel_common"])
    short = {k: (counts[k], m) for k, m in MINIMUMS.items() if counts[k] < m}
    out["counts"] = counts
    out["per_split"] = {k: {sp: len(v) for sp, v in d.items()} for k, d in out["pools"].items()}
    json.dump(out, open("results/step0_v04/lines_v04.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("counts", counts, "per split", out["per_split"])
    print("MINIMUM NOT MET (stop and tell the user):" if short else "minimums met", short or "")


if __name__ == "__main__":
    {"prepare": prepare, "collect": collect, "assign": assign}[sys.argv[1]]()
